    PermisoRol = apps.get_model('usuarios', 'PermisoRol')
    nuevo, _ = Permiso.objects.get_or_create(
        nom_permiso='AUD_CONSULTAR', defaults={'desc_permiso': 'Ver el log de auditoría (quién modificó o anuló qué)'})
    for pr in PermisoRol.objects.filter(idPermiso__nom_permiso='ROL_GESTIONAR'):
        PermisoRol.objects.get_or_create(idRol_id=pr.idRol_id, idPermiso=nuevo)


